ITEMS = []
def add(it): ITEMS.append(it)
TOP = dict(def_=B('Tủ lạnh, bơm nhiệt, COP', 'Refrigerators, heat pumps, COP'), lat=B('Ẩn nhiệt và chuyển pha', 'Latent heat, phase change'),
           dome=B('Vùng hơi ẩm và log p–h', 'Wet region and log p–h'), carnot=B('Chu trình Carnot đảo ngược', 'Reversed Carnot cycle'),
           vcrc=B('Chu trình nén hơi lý tưởng', 'Ideal vapor-compression cycle'), real=B('Chu trình lạnh thực', 'Real refrigeration cycle'),
           equip=B('Thiết bị lạnh', 'Refrigerating equipment'), pack=B('Cooling pack / ACM', 'Cooling pack / ACM'),
           gas=B('Chu trình khí lạnh', 'Gas refrigeration cycle'))
def S(n, vi, en):
    d = B(vi, en); d['_n'] = n; return d                      # question text; the source chip "Slide Ch.3 tr.n: <topic>" is built in Mq/T
def CHKS(n): return B(f'slide Ch.3 tr.{n} (đã xem ảnh)', f'slide Ch.3 p.{n} (image viewed)')
def _src(q, topic, src):
    n = q.pop('_n', None)
    return (B(f"Slide Ch.3 tr.{n}: {topic['vi']}", f"Slide Ch.3 p.{n}: {topic['en']}"), True) if n is not None else (src, False)
def Mq(q, correct, wrongs, expl, lvl, topic, src, check, fixed=False):
    """text options (vi/en pairs): correct and wrongs are B(...) dicts."""
    src, _ = _src(q, topic, src); opts = [correct] + list(wrongs)
    add(mcq(q, opts, 0, expl, lvl, topic, src, 'bo_sung', check, fixed=fixed))
def T(q, truth, expl, lvl, topic, x, check=None):
    src, auto = _src(q, topic, x); add(tf(q, truth, expl, lvl, topic, src, 'bo_sung', check if check is not None else x))

