FE = {}
def fe(num, q_vi, q_en, options, correct_text, expl_vi, expl_en, lvl, topic, route):
    opts = [opt(o) for o in options]; k = options.index(correct_text)
    add(mcq(B(f'Cengel Bài {num} (FE). {q_vi}', f'Cengel Problem {num} (FE). {q_en}'), opts, k, B(expl_vi, expl_en), lvl, topic, B(f'Cengel Bài {num} (FE)', f'Cengel Problem {num} (FE)'), 'goc',
            B(f'sách không in đáp án FE: script verify_m03 (2 đường: {route})', f'the book prints no FE answers: script verify_m03 (2 routes: {route})'), fixed=True))
